for fn in ("/proc/net/tcp","/proc/net/tcp6"):
    try:
        lines=open(fn).read().splitlines()[1:]
    except Exception as e:
        print(fn,"ERR",e); continue
    for l in lines:
        p=l.split()
        if p[3]=="0A":  # LISTEN
            ip,port=p[1].split(":")
            print(f"{fn} listen port {int(port,16)}")
EOF
